items.css:
.hero{max-width:900px;margin:0 auto;padding:5rem 1.5rem;text-align:center}
.hero-kicker{color:#00ff88;letter-spacing:.3em;font-size:.72rem;margin:0 0 1.2rem}
.hero-title{font-size:clamp(2.4rem,6vw,4.2rem);line-height:1.05;margin:0 0 1.2rem;color:#f2f2f2}
.hero-title span{background:linear-gradient(100deg,#00ff88,#0088ff 60%,#ff0080);-webkit-background-clip:text;background-clip:text;color:transparent}
.hero-sub{color:#999;max-width:560px;margin:0 auto 2rem}
.hero-ctas{display:flex;gap:.9rem;justify-content:center;flex-wrap:wrap}
.btn-p{background:#00ff88;color:#04120a;font-weight:700;padding:.8rem 1.6rem;border-radius:.6rem;text-decoration:none}
.btn-g{border:1px solid #333;color:#eee;padding:.8rem 1.6rem;border-radius:.6rem;text-decoration:none}
.btn-g:hover{border-color:#00ff88;color:#00ff88}
.hero-stats{display:flex;gap:2.4rem;justify-content:center;margin-top:3rem;flex-wrap:wrap}
.hero-stats div{display:flex;flex-direction:column}
.hero-stats b{color:#fff;font-size:1.3rem}.hero-stats span{color:#777;font-size:.75rem}

.price-wrap{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:1.2rem;max-width:960px;margin:0 auto;padding:2rem 1.5rem}
.price{background:#141414;border:1px solid #222;border-radius:1rem;padding:1.8rem;position:relative}
.price.hot{border-color:#00ff88;box-shadow:0 0 30px rgba(0,255,136,.12)}
.price em{position:absolute;top:-.8rem;left:50%;transform:translateX(-50%);background:#00ff88;color:#04120a;font-style:normal;font-size:.68rem;font-weight:700;padding:.2rem .8rem;border-radius:1rem}
.price h3{margin:0 0 .4rem;color:#eee}.p-num{font-size:2.2rem;color:#00ff88;margin:.4rem 0 1rem;font-weight:700}
.price ul{list-style:none;padding:0;margin:0 0 1.4rem;color:#999;font-size:.88rem}
.price ul li{padding:.3rem 0;border-bottom:1px solid #1e1e1e}
.price a{display:block;text-align:center;border:1px solid #333;color:#eee;text-decoration:none;padding:.7rem;border-radius:.6rem}
.price.hot a{background:#00ff88;color:#04120a;border-color:#00ff88;font-weight:700}

.ft{background:#0d0d0d;border-top:1px solid #222;margin-top:3rem}
.ft-grid{display:grid;grid-template-columns:2fr 1fr 1fr 1fr;gap:2rem;max-width:1000px;margin:0 auto;padding:2.6rem 1.5rem}
.ft-grid b{color:#00ff88;display:block;margin-bottom:.8rem;font-size:.85rem}
.ft-grid a{display:block;color:#999;text-decoration:none;font-size:.85rem;padding:.25rem 0}
.ft-grid a:hover{color:#00ff88}.ft-grid p{color:#777;font-size:.85rem}
.ft-bar{display:flex;justify-content:space-between;max-width:1000px;margin:0 auto;padding:1.1rem 1.5rem;border-top:1px solid #1a1a1a;color:#555;font-size:.75rem;flex-wrap:wrap;gap:.5rem}
@media(max-width:640px){.ft-grid{grid-template-columns:1fr 1fr}}

.contact{max-width:620px;margin:2rem auto;background:#141414;border:1px solid #222;border-radius:1rem;padding:2rem}
.contact h2{margin:0 0 1.4rem;color:#f2f2f2}
.c-row{display:grid;grid-template-columns:1fr 1fr;gap:1rem}
.contact label{display:block;color:#aaa;font-size:.78rem;margin-bottom:1rem}
.contact input,.contact select,.contact textarea{width:100%;margin-top:.4rem;background:#0d0d0d;border:1px solid #2c2c2c;color:#eee;border-radius:.55rem;padding:.7rem .9rem;font:inherit}
.contact input:focus,.contact select:focus,.contact textarea:focus{outline:none;border-color:#00ff88;box-shadow:0 0 0 1px #00ff88}
.contact button{background:#00ff88;color:#04120a;font-weight:700;border:0;border-radius:.55rem;padding:.8rem 1.6rem;cursor:pointer;font:inherit}
@media(max-width:560px){.c-row{grid-template-columns:1fr}}

.tabs{max-width:640px;margin:2rem auto;background:#141414;border:1px solid #222;border-radius:1rem;overflow:hidden}
.tab-bar{display:flex;border-bottom:1px solid #222}
.tab{flex:1;background:none;border:0;border-bottom:2px solid transparent;color:#999;padding:.9rem;cursor:pointer;font:inherit}
.tab.on{color:#00ff88;border-bottom-color:#00ff88;font-weight:700}
.tab-p{display:none;padding:1.6rem;color:#bbb}
.tab-p.on{display:block;animation:mup .2s ease}
.tab-p h4{margin:0 0 .5rem;color:#eee}
@keyframes mup{from{opacity:0;transform:translateY(6px)}}

.al{display:flex;gap:.7rem;align-items:baseline;border-radius:.7rem;padding:.85rem 1.1rem;margin:.6rem auto;max-width:640px;font-size:.88rem;border:1px solid}
.al b{flex:0 0 auto}.al span{color:#bbb}
.al.ok{border-color:rgba(0,255,136,.4);background:rgba(0,255,136,.06)}.al.ok b{color:#00ff88}
.al.info{border-color:rgba(0,136,255,.4);background:rgba(0,136,255,.06)}.al.info b{color:#0088ff}
.al.warn{border-color:rgba(255,184,107,.4);background:rgba(255,184,107,.06)}.al.warn b{color:#ffb86b}
.al.err{border-color:rgba(255,0,128,.4);background:rgba(255,0,128,.06)}.al.err b{color:#ff0080}

